function validate([word, abbr]) {
  if (typeof word !== 'string' || !/^[a-z]{1,20}$/.test(word)) return 'word has 1 to 20 lowercase letters.';
  if (typeof abbr !== 'string' || !/^[a-z0-9]{1,10}$/.test(abbr)) return 'abbr has 1 to 10 lowercase letters and digits.';
  if ((abbr.match(/[0-9]+/g) || []).some(run => Number(run) > 2147483647)) return 'Every number in abbr fits in a 32-bit signed integer.';
  return null;
}

