function validWordAbbreviation(word, abbr) {
  const tokens = abbr.match(/[0-9]+|[a-z]/g);
  let pattern = '';
  for (const token of tokens) {
    if (/^[a-z]$/.test(token)) {
      pattern += token;
      continue;
    }
    if (token[0] === '0') return false;
    const length = parseInt(token, 10);
    if (length > word.length) return false;
    pattern += '?'.repeat(length);
  }
  if (pattern.length !== word.length) return false;
  for (let k = 0; k < word.length; k++) if (pattern[k] !== '?' && pattern[k] !== word[k]) return false;
  return true;
}

