function generate(rand, size) {
  const pick = text => text[Math.floor(rand() * text.length)];
  const fits = abbr => abbr.length >= 1 && abbr.length <= 10 && (abbr.match(/[0-9]+/g) || []).every(run => Number(run) <= 2147483647);
  for (;;) {
    const n = size === 'large' ? 15 + Math.floor(rand() * 6) : 1 + Math.floor(rand() * 7);
    const alphabet = rand() < 0.5 ? 'ab' : 'abcdefghijklmnopqrstuvwxyz';
    let word = '';
    for (let k = 0; k < n; k++) word += pick(alphabet);
    const replaceRate = size === 'large' ? 0.6 : 0.2 + rand() * 0.5;
    let abbr = '';
    let i = 0;
    while (i < n) {
      if (rand() < replaceRate && !/[0-9]$/.test(abbr)) {
        const length = 1 + Math.floor(rand() * (n - i));
        abbr += String(length);
        i += length;
      } else {
        abbr += word[i];
        i++;
      }
    }
    const r = rand();
    const at = Math.floor(rand() * (abbr.length + 1));
    if (r < 0.45) {
      // keep the valid abbreviation
    } else if (r < 0.55) {
      abbr = abbr.slice(0, at) + pick('abcz') + abbr.slice(at + 1);
    } else if (r < 0.65) {
      abbr = abbr.replace(/[0-9]+/, run => String(Number(run) + (rand() < 0.5 ? 1 : -1)));
    } else if (r < 0.75) {
      abbr = abbr.replace(/[0-9]+/, run => '0' + run);
    } else if (r < 0.82) {
      abbr = abbr.slice(0, at) + '0' + abbr.slice(at);
    } else if (r < 0.9) {
      abbr = abbr.slice(0, at) + abbr.slice(at + 1);
    } else if (r < 0.96) {
      abbr += pick('a1b9');
    } else {
      abbr = pick(['2147483647', 'a999999999', '1' + abbr.slice(1)]);
    }
    if (fits(abbr)) return [word, abbr];
  }
}
